/**
 * 保存单个输入参数（页面「创建参数」入口，逐条 upsert）
 *
 * @param req 保存请求（modelId、productVersionNumber 及参数明细）
 * @return 使用的参数编码（前端未传时为后端生成的编码）
 */
@PostMapping("/input-params/save")
@ResponseBody
public BaseResult<String> saveInputParam(@Validated @RequestBody InputParamSaveReq req) {
    return BaseResult.success(tplInputParamServiceBiz.saveInputParam(req));
}

/**
 * 保存单个输入参数（页面「创建参数」入口）
 * 按 (productResourcePackageid, paramCode) 逐条 upsert，不做整包覆盖
 *
 * @param req 保存请求（modelId、productVersionNumber 及参数明细）
 * @return 使用的参数编码（前端未传时为后端生成的编码）
 */
@Transactional(rollbackFor = Exception.class)
public String saveInputParam(InputParamSaveReq req) {
    validateSaveReq(req);
    // 含计算参数补齐必填列默认值，须在白名单校验与实际落库之前，保证校验的就是落库值
    applyCalcParamDefaults(req);

    String resourcePackageId = req.getModelId().trim() + "_" + req.getProductVersionNumber().trim();
    log.info("saveInputParam start, resourcePackageId={}, paramCode={}, paramName={}",
            resourcePackageId, req.getParamCode(), req.getParamName());

    try {
        // ① 校验产品存在：配置页允许只手工配规则、不上传资源包，
        // 此时补登记一行基础信息，后续按 modelId+版本 的查询（列表、云存储映射、配单流程）才不会落空
        if (!tplProductBaseInformationRegisterBiz.registerPackageIfAbsent(
                req.getModelId().trim(), req.getProductVersionNumber().trim())) {
            throw new BusinessPlusException(HipeiErrorCode.ParamError.ERR_PARAM_INVALID.getStrCode(),
                    "产品不存在", "产品不存在");
        }

        // ② 解析参数编码：前端不传则按 030103 段内最大号 +1 生成
        String paramCode = resolveParamCode(resourcePackageId, req.getParamCode());

        // ③ 校验参数类型白名单（拦截导入链路遗留的脏数据口径，如 double）
        if (StringUtils.isNotBlank(req.getParamType())
                && !PARAM_TYPE_WHITELIST.contains(req.getParamType())) {
            throw new BusinessPlusException(HipeiErrorCode.ParamError.ERR_PARAM_INVALID.getStrCode(),
                    "paramType非法:" + req.getParamType(), "参数类型必须是 整数/浮点数/下拉框/布尔 之一");
        }

        // ④ 校验含计算参数的公式语法（$$(paramCode) 引用语法，等号由 checkExpression 拦截）
        if (StringUtils.isNotBlank(req.getCalRule())) {
            QlExpressTool.checkExpression(req.getCalRule(), new HashMap<>());
        }

        // ⑤ upsert：按 (resourcePackageId, paramCode) 命中则更新，未命中则插入
        LambdaQueryWrapper<TplInputParamTab> existWrapper = new LambdaQueryWrapper<TplInputParamTab>()
                .eq(TplInputParamTab::getProductResourcePackageid, resourcePackageId)
                .eq(TplInputParamTab::getParamCode, paramCode);
        TplInputParamTab existing = tplInputParamService.getOne(existWrapper);
        if (existing != null) {
            applySaveReqToEntity(req, existing, paramCode);
            tplInputParamService.updateById(existing);
            log.info("saveInputParam: updated existing param, resourcePackageId={}, paramCode={}",
                    resourcePackageId, paramCode);
        } else {
            TplInputParamTab entity = TplInputParamTab.builder()
                    .productResourcePackageid(resourcePackageId)
                    .createTime(LocalDateTime.now())
                    .build();
            applySaveReqToEntity(req, entity, paramCode);
            tplInputParamService.save(entity);
            log.info("saveInputParam: inserted new param, resourcePackageId={}, paramCode={}",
                    resourcePackageId, paramCode);
        }

        log.info("saveInputParam success, resourcePackageId={}, paramCode={}", resourcePackageId, paramCode);
        return paramCode;
    } catch (BusinessPlusException e) {
        throw e;
    } catch (QLException qlException) {
        // 公式语法错误：把具体语法信息带给前端，而不是兜底成通用错误
        log.warn("saveInputParam formula check failed, calRule={}", req.getCalRule());
        throw new BusinessPlusException(HipeiErrorCode.ParamError.ERR_PARAM_INVALID.getStrCode(),
                "公式语法错误:" + qlException.getMessage(),
                "公式语法错误：" + qlException.getMessage());
    } catch (DataAccessException dataAccessException) {
        // 数据库写入失败：把真实原因（缺列、超长、约束冲突等）带进日志与提示，不再统一兜底成通用错误
        String cause = dataAccessException.getMostSpecificCause().getMessage();
        log.error("saveInputParam database failed, resourcePackageId={}, paramName={}, cause={}",
                resourcePackageId, req.getParamName(), cause, dataAccessException);
        throw new BusinessPlusException(HipeiErrorCode.ParamError.ERR_PARAM_INVALID.getStrCode(),
                "参数保存失败:" + cause,
                "参数保存失败，请检查参数配置");
    } catch (Exception e) {
        log.error("saveInputParam failed, resourcePackageId={}, paramName={}",
                resourcePackageId, req.getParamName(), e);
        throw new BusinessPlusException(HipeiErrorCode.ServiceError.ERR_SERVICE_INNER, e,
                HipeiErrorCode.ServiceError.ERR_SERVICE_INNER.getStrMsgShow());
    }
}
